#include <string.h>
#include <stdlib.h>
typedef void (*naupd_t)(void*, double*, double*, int, int*, double*, double*);

/* Blocked ELL: rows grouped in blocks of 4; within block, column-major padded entries.
   Each row's summation order is identical to CSR order (pads are 0*x[0] = +0 adds). */
static void mv_ell(int n, int nb, const int* boff, const int* blen,
                   const int* eix, const double* edat, const double* x, double* y)
{
    for (int b = 0; b < nb; b++) {
        const int* ix = eix + boff[b];
        const double* d = edat + boff[b];
        int L = blen[b];
        double s0 = 0.0, s1 = 0.0, s2 = 0.0, s3 = 0.0;
        for (int j = 0; j < L; j++) {
            s0 += d[4*j+0] * x[ix[4*j+0]];
            s1 += d[4*j+1] * x[ix[4*j+1]];
            s2 += d[4*j+2] * x[ix[4*j+2]];
            s3 += d[4*j+3] * x[ix[4*j+3]];
        }
        int r = 4*b;
        y[r] = s0;
        if (r+1 < n) y[r+1] = s1;
        if (r+2 < n) y[r+2] = s2;
        if (r+3 < n) y[r+3] = s3;
    }
}

int run_loop(void* fp, char* st, double* resid, double* v, int* ipntr,
             double* workd, double* workl, int n,
             const int* indptr, const int* indices, const double* data)
{
    naupd_t f = (naupd_t)fp;
    int nb = (n + 3) / 4;
    int* boff = (int*)malloc(sizeof(int) * (nb + 1));
    int* blen = (int*)malloc(sizeof(int) * nb);
    int tot = 0;
    for (int b = 0; b < nb; b++) {
        int L = 0;
        for (int q = 0; q < 4; q++) {
            int r = 4*b + q;
            if (r < n) { int l = indptr[r+1] - indptr[r]; if (l > L) L = l; }
        }
        blen[b] = L; boff[b] = tot; tot += 4 * L;
    }
    int* eix = (int*)calloc(tot > 0 ? tot : 1, sizeof(int));
    double* edat = (double*)calloc(tot > 0 ? tot : 1, sizeof(double));
    for (int b = 0; b < nb; b++) {
        for (int q = 0; q < 4; q++) {
            int r = 4*b + q;
            if (r >= n) continue;
            int s = indptr[r], l = indptr[r+1] - s;
            for (int j = 0; j < l; j++) {
                eix[boff[b] + 4*j + q] = indices[s + j];
                edat[boff[b] + 4*j + q] = data[s + j];
            }
        }
    }
    int ido;
    for (;;) {
        f(st, resid, v, n, ipntr, workd, workl);
        ido = *(int*)(st + 0x34);
        if (ido == 1 || ido == 5) {
            mv_ell(n, nb, boff, blen, eix, edat, workd + ipntr[0], workd + ipntr[1]);
        } else break;
    }
    free(boff); free(blen); free(eix); free(edat);
    return ido;
}
