{"command": "cat > fastarnoldi.c <<'E'
#include <string.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>
typedef void (*naupd_t)(void*, double*, double*, int, int*, double*, double*);

typedef struct {
    int n, nb;
    const int *boff, *blen, *eix;
    const double *edat;
    const double *x; double *y;
} mvctx;

/* Each row summed sequentially in CSR order -> bit-identical to scipy csr_matvec. */
static void mv_blocks(const mvctx* c, int b0, int b1)
{
    int n = c->n;
    const double* x = c->x; double* y = c->y;
    for (int b = b0; b < b1; b++) {
        const int* ix = c->eix + c->boff[b];
        const double* d = c->edat + c->boff[b];
        int L = c->blen[b];
        double s0 = 0.0, s1 = 0.0, s2 = 0.0, s3 = 0.0;
        for (int j = 0; j < L; j++) {
            s0 += d[4*j+0] * x[ix[4*j+0]];
            s1 += d[4*j+1] * x[ix[4*j+1]];
            s2 += d[4*j+2] * x[ix[4*j+2]];
            s3 += d[4*j+3] * x[ix[4*j+3]];
        }
        int r = 4*b;
        y[r] = s0;
        if (r+1 < n) y[r+1] = s1;
        if (r+2 < n) y[r+2] = s2;
        if (r+3 < n) y[r+3] = s3;
    }
}

#define MAXT 16
typedef struct {
    mvctx* c;
    int nt;
    int split[MAXT+1];
    _Atomic long gen;
    _Atomic int done;
    _Atomic int quit;
} pool_t;
typedef struct { pool_t* p; int id; } warg;

static void* worker(void* a)
{
    warg* w = (warg*)a; pool_t* p = w->p; int id = w->id;
    long seen = 0;
    for (;;) {
        long g;
        while ((g = atomic_load_explicit(&p->gen, memory_order_acquire)) == seen) {
            if (atomic_load_explicit(&p->quit, memory_order_relaxed)) return NULL;
#if defined(__x86_64__)
            __builtin_ia32_pause();
#endif
        }
        seen = g;
        mv_blocks(p->c, p->split[id], p->split[id+1]);
        atomic_fetch_add_explicit(&p->done, 1, memory_order_acq_rel);
    }
}

int run_loop(void* fp, char* st, double* resid, double* v, int* ipntr,
             double* workd, double* workl, int n,
             const int* indptr, const int* indices, const double* data, int nthreads)
{
    naupd_t f = (naupd_t)fp;
    int nb = (n + 3) / 4;
    int* boff = (int*)malloc(sizeof(int) * (nb + 1));
    int* blen = (int*)malloc(sizeof(int) * nb);
    int tot = 0;
    for (int b = 0; b < nb; b++) {
        int L = 0;
        for (int q = 0; q < 4; q++) {
            int r = 4*b + q;
            if (r < n) { int l = indptr[r+1] - indptr[r]; if (l > L) L = l; }
        }
        blen[b] = L; boff[b] = tot; tot += 4 * L;
    }
    boff[nb] = tot;
    int* eix = (int*)calloc(tot > 0 ? tot : 1, sizeof(int));
    double* edat = (double*)calloc(tot > 0 ? tot : 1, sizeof(double));
    for (int b = 0; b < nb; b++) {
        for (int q = 0; q < 4; q++) {
            int r = 4*b + q;
            if (r >= n) continue;
            int s = indptr[r], l = indptr[r+1] - s;
            for (int j = 0; j < l; j++) {
                eix[boff[b] + 4*j + q] = indices[s + j];
                edat[boff[b] + 4*j + q] = data[s + j];
            }
        }
    }
    mvctx c = { n, nb, boff, blen, eix, edat, NULL, NULL };
    int nt = nthreads; if (nt < 1) nt = 1; if (nt > MAXT) nt = MAXT; if (nt > nb) nt = nb > 0 ? nb : 1;
    pool_t pool; memset(&pool, 0, sizeof(pool));
    pool.c = &c; pool.nt = nt;
    /* split blocks balancing nnz */
    pool.split[0] = 0;
    { int k = 1; long acc = 0;
      for (int b = 0; b < nb && k < nt; b++) {
          acc += 4L * blen[b];
          if (acc * nt >= (long)tot * k) pool.split[k++] = b + 1;
      }
      while (k < nt) pool.split[k++] = nb;
      pool.split[nt] = nb; }
    pthread_t th[MAXT]; warg wa[MAXT];
    for (int i = 1; i < nt; i++) { wa[i].p = &pool; wa[i].id = i; pthread_create(&th[i], NULL, worker, &wa[i]); }
    int ido;
    long gen = 0;
    for (;;) {
        f(st, resid, v, n, ipntr, workd, workl);
        ido = *(int*)(st + 0x34);
        if (ido == 1 || ido == 5) {
            c.x = workd + ipntr[0]; c.y = workd + ipntr[1];
            if (nt > 1) {
                atomic_store_explicit(&pool.done, 0, memory_order_relaxed);
                atomic_store_explicit(&pool.gen, ++gen, memory_order_release);
                mv_blocks(&c, pool.split[0], pool.split[1]);
                while (atomic_load_explicit(&pool.done, memory_order_acquire) < nt - 1) {
#if defined(__x86_64__)
                    __builtin_ia32_pause();
#endif
                }
            } else {
                mv_blocks(&c, 0, nb);
            }
        } else break;
    }
    atomic_store(&pool.quit, 1);
    for (int i = 1; i < nt; i++) pthread_join(th[i], NULL);
    free(boff); free(blen); free(eix); free(edat);
    return ido;
}
