{"command": "cat > fastarnoldi.c <<'E'
#include <string.h>
#include <stdlib.h>
typedef void (*naupd_t)(void*, double*, double*, int, int*, double*, double*);
#define B 8
/* Rows sorted by length, grouped into blocks of B, entries interleaved.
   Each row is summed sequentially in its CSR order (padding adds +0.0 at the end
   only when the row is shorter, and s + 0*x == s exactly for finite x), so
   results are bit-identical to scipy's csr_matvec. */
typedef struct { int len, row; } rl;
static int cmp(const void* a, const void* b) {
    const rl* x = a; const rl* y = b;
    if (x->len != y->len) return x->len - y->len;
    return x->row - y->row;
}
static void mv(int nb, const int* boff, const int* blen, const int* brow,
               const int* eix, const double* edat, const double* x, double* y)
{
    for (int b = 0; b < nb; b++) {
        const int* ix = eix + boff[b];
        const double* d = edat + boff[b];
        int L = blen[b];
        double s[B];
        for (int q = 0; q < B; q++) s[q] = 0.0;
        for (int j = 0; j < L; j++) {
            for (int q = 0; q < B; q++) s[q] += d[B*j+q] * x[ix[B*j+q]];
        }
        const int* rr = brow + B*b;
        for (int q = 0; q < B; q++) if (rr[q] >= 0) y[rr[q]] = s[q];
    }
}

int run_loop(void* fp, char* st, double* resid, double* v, int* ipntr,
             double* workd, double* workl, int n,
             const int* indptr, const int* indices, const double* data, int nthreads)
{
    naupd_t f = (naupd_t)fp;
    rl* order = (rl*)malloc(sizeof(rl) * (n > 0 ? n : 1));
    for (int i = 0; i < n; i++) { order[i].len = indptr[i+1] - indptr[i]; order[i].row = i; }
    qsort(order, n, sizeof(rl), cmp);
    int nb = (n + B - 1) / B;
    int* boff = (int*)malloc(sizeof(int) * (nb + 1));
    int* blen = (int*)malloc(sizeof(int) * (nb + 1));
    int* brow = (int*)malloc(sizeof(int) * (nb * B + 1));
    int tot = 0;
    for (int b = 0; b < nb; b++) {
        int L = 0;
        for (int q = 0; q < B; q++) {
            int k = B*b + q;
            if (k < n) { brow[k] = order[k].row; if (order[k].len > L) L = order[k].len; }
            else brow[k] = -1;
        }
        blen[b] = L; boff[b] = tot; tot += B * L;
    }
    int* eix = (int*)calloc(tot > 0 ? tot : 1, sizeof(int));
    double* edat = (double*)calloc(tot > 0 ? tot : 1, sizeof(double));
    for (int b = 0; b < nb; b++) {
        for (int q = 0; q < B; q++) {
            int k = B*b + q;
            if (k >= n) continue;
            int r = order[k].row;
            int s = indptr[r], l = indptr[r+1] - s;
            for (int j = 0; j < l; j++) {
                eix[boff[b] + B*j + q] = indices[s + j];
                edat[boff[b] + B*j + q] = data[s + j];
            }
        }
    }
    int ido;
    for (;;) {
        f(st, resid, v, n, ipntr, workd, workl);
        ido = *(int*)(st + 0x34);
        if (ido == 1 || ido == 5) {
            mv(nb, boff, blen, brow, eix, edat, workd + ipntr[0], workd + ipntr[1]);
        } else break;
    }
    free(order); free(boff); free(blen); free(brow); free(eix); free(edat);
    return ido;
}
