#include <string.h>
#include <stdlib.h>
#include <math.h>
typedef void (*naupd_t)(void*, double*, double*, int, int*, double*, double*);
#define B 4
static void mv(int n, int nb, const int* boff, const int* blen,
               const int* eix, const double* edat, const double* x, double* y)
{
    for (int b = 0; b < nb; b++) {
        const int* ix = eix + boff[b];
        const double* d = edat + boff[b];
        int L = blen[b];
        double s0 = 0.0, s1 = 0.0, s2 = 0.0, s3 = 0.0;
        for (int j = 0; j < L; j++) {
            s0 += d[4*j+0] * x[ix[4*j+0]];
            s1 += d[4*j+1] * x[ix[4*j+1]];
            s2 += d[4*j+2] * x[ix[4*j+2]];
            s3 += d[4*j+3] * x[ix[4*j+3]];
        }
        int r = 4*b;
        y[r] = s0;
        if (r+1 < n) y[r+1] = s1;
        if (r+2 < n) y[r+2] = s2;
        if (r+3 < n) y[r+3] = s3;
    }
}

/* Returns 1 if the top-(k+1) Ritz values by modulus all have bounds <= thr*|ritz|. */
static int top_converged(const double* workl, int ncv, int k, double thr)
{
    const double* rr = workl + ncv*ncv;
