static double dlapy2(double x,double y){
  int xn=isnan(x), yn=isnan(y); if(xn) return x; if(yn) return y;
  double xa=fabs(x), ya=fabs(y); double w=xa>ya?xa:ya, z=xa<ya?xa:ya;
  if(z==0.0 || w>DBL_MAX) return w;
  return w*sqrt(1.0+(z/w)*(z/w));
}
/* Blue's algorithm dnrm2 (LAPACK 3.10) */
static double dnrm2_blue(int n,const double*x){
  const double tsml=1.4916681462400413e-154, tbig=1.9979190722022350e+146, ssml=4.4989137945431964e+161, sbig=1.1113793747425387e-162;
  double asml=0,amed=0,abig=0; int notbig=1;
  for(int i=0;i<n;i++){ double ax=fabs(x[i]);
    if(ax>tbig){ abig+= (ax*sbig)*(ax*sbig); notbig=0; }
    else if(ax<tsml){ if(notbig) asml+=(ax*ssml)*(ax*ssml); }
    else amed+=ax*ax; }
  double scl,sumsq;
  if(abig>0){ if(amed>0||isnan(amed)) abig+=(amed*sbig)*sbig; scl=1.0/sbig; sumsq=abig; }
  else if(asml>0){ if(amed>0||isnan(amed)){ amed=sqrt(amed); asml=sqrt(asml)/ssml;
      double ymin,ymax; if(asml>amed){ymin=amed;ymax=asml;}else{ymin=asml;ymax=amed;}
      scl=1.0; sumsq=ymax*ymax*(1.0+(ymin/ymax)*(ymin/ymax)); }
    else { scl=1.0/ssml; sumsq=asml; } }
  else { scl=1.0; sumsq=amed; }
  return scl*sqrt(sumsq);
}
static double dnrm2_classic(int n,const double*x){
  if(n<1) return 0; if(n==1) return fabs(x[0]);
  double scale=0, ssq=1;
  for(int i=0;i<n;i++) if(x[i]!=0){ double a=fabs(x[i]); if(scale<a){ ssq=1+ssq*(scale/a)*(scale/a); scale=a;} else ssq+=(a/scale)*(a/scale);}
  return scale*sqrt(ssq);
}
int variant=0;
void my_larfg(const int* n_, double* alpha, double* x, const int* incx, double* tau){
  int n=*n_;
  if(n<=1){*tau=0;return;}
  double xnorm = variant==0? dnrm2_blue(n-1,x) : variant==1? dnrm2_classic(n-1,x) : sqrt(n-1==1? x[0]*x[0] : x[0]*x[0]+x[1]*x[1]);
  if(xnorm==0.0){*tau=0;return;}
  double beta = -copysign(dlapy2(*alpha,xnorm), *alpha);
  double safmin = DBL_MIN/ (DBL_EPSILON/2) ; /* dlamch('S')/dlamch('E') */
  int knt=0;
  if(fabs(beta)<safmin){
    double rsafmn=1.0/safmin;
    do{ knt++; for(int i=0;i<n-1;i++) x[i]*=rsafmn; beta*=rsafmn; *alpha*=rsafmn; } while(fabs(beta)<safmin && knt<20);
    xnorm = variant==0? dnrm2_blue(n-1,x) : dnrm2_classic(n-1,x);
    beta = -copysign(dlapy2(*alpha,xnorm), *alpha);
  }
  *tau=(beta-*alpha)/beta;
  double sc=1.0/(*alpha-beta);
  for(int i=0;i<n-1;i++) x[i]*=sc;
  for(int j=0;j<knt;j++) beta*=safmin;
  *alpha=beta;
}
