/* test candidate formulas for dger; return mask of matching variants */
int test_ger(ger_t g,int m,int n,double al,const double*x,const double*y,const double*A0){
  double A[4096],B[4096]; memcpy(A,A0,8*m*n); g(&m,&n,&al,x,&(int){1},y,&(int){1},A,&m);
  int mask=0;
