    for(int j=0;j<n;j++) for(int i=0;i<m;i++){ double*b=&B[i+j*m];
      switch(v){
      case 0: *b = *b + x[i]*(al*y[j]); break;
      case 1: *b = fma(x[i], al*y[j], *b); break;
