      case 3: *b = fma(al*x[i], y[j], *b); break;
      case 4: *b = fma(al, x[i]*y[j], *b); break;
      case 5: *b = *b + al*(x[i]*y[j]); break;
      } }
    if(!memcmp(A,B,8*m*n)) mask|=1<<v; }
  return mask;
}
